def minPath(grid, k):
    if k == 1:
        return [1]

    n = len(grid)
    pos = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                pos = (i, j)
                break
        if pos is not None:
            break

    r, c = pos
    second = min(
        grid[r + dr][c + dc]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
        if 0 <= r + dr < n and 0 <= c + dc < n
    )

    return [1, second] * (k // 2) + [1] * (k % 2)
