class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # At the same timestamp, OFFLINE events must be processed before MESSAGE events.
        events = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        online = [True] * numberOfUsers
        offline_until = [0] * numberOfUsers
        mentions = [0] * numberOfUsers

        for typ, ts, data in events:
            t = int(ts)

            # Process automatic re-online status changes at this timestamp.
            for i in range(numberOfUsers):
                if not online[i] and offline_until[i] <= t:
                    online[i] = True

            if typ == "OFFLINE":
                uid = int(data)
                online[uid] = False
                offline_until[uid] = t + 60
            else:  # MESSAGE
                for token in data.split():
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    else:  # id<number>
                        uid = int(token[2:])
                        mentions[uid] += 1

        return mentions
