class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best_gain = 0

        for target in range(1, 51):
            if target == k:
                continue

            cur = 0
            max_gain = 0

            for v in nums:
                if v == target:
                    cur += 1
                elif v == k:
                    cur -= 1

                if cur < 0:
                    cur = 0
                if cur > max_gain:
                    max_gain = cur

            best_gain = max(best_gain, max_gain)

        return base + best_gain
